        if (!m->valid || frame_no - m->born < MAP_AGE || frame_no - m->used < MAP_COOL) continue;
        double d[3], Pc[3];
        for (int i = 0; i < 3; i++) d[i] = m->pw[i] - pwc[i];
        m3tvec(Rwc, d, Pc);
        if (Pc[2] < 0.3 || Pc[2] > 8.0) continue;
        double u = fx * Pc[0] / Pc[2] + cx, v = fy * Pc[1] / Pc[2] + cy;
        int S = S0;
        int cu = (int)floor(u * 0.5 + 0.5), cv = (int)floor(v * 0.5 + 0.5);
        int near_track = 0;
        if (MAP_NEAR) {
            double bd = 100; int bi = -1;
            for (int i = 0; i < MAX_TRACKS; i++)
                if (tracks[i].alive) { double dd = fabs(tracks[i].x - u) + fabs(tracks[i].y - v); if (dd < bd) { bd = dd; bi = i; } }
            if (bi >= 0 && bd < 14) { cu = (int)floor(tracks[bi].x * 0.5 + 0.5); cv = (int)floor(tracks[bi].y * 0.5 + 0.5); S = 3; near_track = 2; }
        }
        if (cu < r + S + 1 || cv < r + S + 1 || cu >= w - r - S - 1 || cv >= h - r - S - 1) continue;
        double d0[3], n1 = 0, n0 = 0, dotv = 0;
        for (int i = 0; i < 3; i++) { d0[i] = m->pw[i] - m->c0[i]; n1 += d[i] * d[i]; n0 += d0[i] * d0[i]; dotv += d[i] * d0[i]; }
        n1 = sqrt(n1); n0 = sqrt(n0);
        if (dotv < cosang * n1 * n0 || n1 < 0.75 * n0 || n1 > 1.33 * n0) continue;
        if (!near_track)
            for (int i = 0; i < MAX_TRACKS; i++)
                if (tracks[i].alive && fabs(tracks[i].x - u) < 6 && fabs(tracks[i].y - v) < 6) { near_track = 1; break; }
        if (near_track == 1) continue;
