        double norm = 0, v[2 * MAX_OBS];
        for (int i = c; i < m; i++) norm += Hf[i * 3 + c] * Hf[i * 3 + c];
        norm = sqrt(norm);
        if (norm < 1e-14) continue;
        double alpha = Hf[c * 3 + c] > 0 ? -norm : norm, vn = 0;
        for (int i = c; i < m; i++) v[i] = Hf[i * 3 + c];
        v[c] -= alpha;
