            const v128_t w0 = wasm_i16x8_splat((short)(256 - f8)), w1 = wasm_i16x8_splat((short)f8), W0 = wasm_i16x8_splat((short)(32767 - f15)), W1 = wasm_i16x8_splat((short)f15);
            v128_t hA[11], hB[11], hC[11];
            const uint8_t *p = I0 + yi * w + xi;
            for (int r = 0; r < 11; r++, p += w) { hA[r] = kh(p, w0, w1); hC[r] = kh(p + 1, w0, w1); hB[r] = kh(p + 2, w0, w1); }
            v128_t C[10];
